1	// Package relayproof implements cross-chain message verification.
2	package relayproof
3	
4	import (
5		"encoding/binary"
6		"sort"
7		"strconv"
8	)
9	
10	// Header is a light-client header at a known height.
11	type Header struct {
12		Chain   string
13		Height  int64
14		Root    string
15		Trusted bool
16	}
17	
18	// Message is one outbound cross-chain message awaiting delivery.
19	type Message struct {
20		ID      string
21		From    string
22		To      string
23		Nonce   uint64
24		Payload string
25		ProofAt int64
26	}
27	
28	// Delivery is the outcome of a relay attempt.
29	type Delivery struct {
30		Message string
31		Status  string
32		Reason  string
33	}
34	
35	// consumeToken is the injective identity of a (source chain, destination
36	// chain, nonce) consumption. Replay protection must judge consumption by
37	// these three values independently: chain names are kept as their raw UTF-8
38	// bytes, including ':' and U+0000, so joining them with a separator character
39	// would merge distinct paths (e.g. "a:b"->"c" with "a"->"b:c"). Length
40	// prefixes on the two strings make the encoding unambiguous for every
41	// possible string content without forbidding, truncating or rewriting names.
42	type consumeToken struct {
43		from  string
44		to    string
45		nonce uint64
46	}
47	
48	func newConsumeToken(from, to string, nonce uint64) consumeToken {
49		return consumeToken{from: from, to: to, nonce: nonce}
50	}
51	
52	// marshal renders the token as a self-delimited byte sequence. It is only
53	// used where a string key is required; equality on the struct itself is the
54	// primary identity comparison and remains exact for all strings.
55	func (t consumeToken) marshal() string {
56		var buf []byte
57		var lenBuf [8]byte
58		binary.BigEndian.PutUint64(lenBuf[:], uint64(len(t.from)))
59		buf = append(buf, lenBuf[:]...)
60		buf = append(buf, t.from...)
61		binary.BigEndian.PutUint64(lenBuf[:], uint64(len(t.to)))
62		buf = append(buf, lenBuf[:]...)
63		buf = append(buf, t.to...)
64		binary.BigEndian.PutUint64(lenBuf[:], t.nonce)
65		buf = append(buf, lenBuf[:]...)
66		return string(buf)
67	}
68	
69	// String renders a human-readable, quoted view for diagnostics. It is never
70	// used as an identity key.
71	func (t consumeToken) String() string {
72		return strconv.QuoteToASCII(t.from) + " -> " + strconv.QuoteToASCII(t.to) +
73			" nonce " + strconv.FormatUint(t.nonce, 10)
74	}
75	
76	// Verify accepts a message only when the header covering it is known and trusted.
77	func Verify(headers map[string]Header, message Message, consumed map[string]bool) Delivery {
78		header, ok := headers[message.From]
79		if !ok {
80			return Delivery{Message: message.ID, Status: "rejected", Reason: "unknown source chain"}
81		}
82		if !header.Trusted || header.Height < message.ProofAt {
83			return Delivery{Message: message.ID, Status: "pending", Reason: "header not yet trusted at proof height"}
84		}
85		key := newConsumeToken(message.From, message.To, message.Nonce).marshal()
86		if consumed[key] {
87			return Delivery{Message: message.ID, Status: "rejected", Reason: "replay: nonce already consumed"}
